    void board;
    k.mount(paperMap(0.95, 0.7), "west", 1.6, 1.6, "map");
    k.mount(rosterFrame(0.9, 0.6), "west", 5.05, 1.75, "roster");
    k.mount(keepsakeShelf(1.9, 1, 6), "north", 3.6, 2.5, "keepsakes");
    const rug = k.place(pitchRug(1.2), { x: 2.55, z: 3.3, name: "rug" });
    rug.rotation.y = PI / 4;
    k.place(couch(1.7, "#cbbcab"), { x: 0.55, z: 4.95, rot: PI / 2, footprint: { w: 1.75, d: 0.85 }, name: "couch", movable: true });
    k.station({ id: "couch-a", of: "couch", label: "napping on the couch", activity: "sleep", pos: { x: 0.62, z: 4.55 }, approach: { x: 1.35, z: 4.55 }, seat: 0.36, face: PI / 2, tags: ["rest"] });
    k.station({ id: "couch-b", of: "couch", label: "curled up on the couch", activity: "read", pos: { x: 0.62, z: 5.35 }, approach: { x: 1.35, z: 5.35 }, seat: 0.36, face: PI / 2, tags: ["rest", "calm"] });
    k.place(tossBin(), { x: 4.05, z: 4.55, footprint: { r: 0.3 }, name: "bin" });
    k.place(movingBoxes(4, 4), { x: 3.7, z: 0.75, name: "boxes" });
    k.footprints.push({ x: 3.7, z: 0.75, w: 2.2, d: 0.9, tag: "boxes" });
    const lamp = k.place(floorLamp("#efe4d2"), { x: 0.45, z: 0.45, footprint: { r: 0.26 }, name: "lamp", movable: true });
