    k.station({ id: "read-study", of: "armchair", label: "reading in the armchair", activity: "read", pos: { x: -1.25, z: -4.95 }, approach: { x: -1.9, z: -4.3 }, seat: 0.36, face: -PI * 0.75, tags: ["calm", "research"] });
