  function bunk() {
    const k = new RoomKit("bunk", 1);
    const beds = [
      { x: 2.45, z: -5.45, rot: 0 },
      { x: 4.6, z: -5.45, rot: 0 },
      { x: 0.55, z: -1.35, rot: PI / 2 },
      { x: 5.45, z: -2.75, rot: -PI / 2 }
    ];
    const quilts = [
      ["#d9c7d6", "#c8d4c4"],
      ["#e2d0bd", "#cfd2e0"],
      ["#d0dccd", "#e6cfd1"],
      ["#dcd1e4", "#e4d9c3"]
    ];
    beds.forEach((b, i) => {
      const bb = k.place(bunkBed(1.85, 0.95, quilts[i]), { x: b.x, z: b.z, rot: b.rot, footprint: { w: 1.9, d: 1 } });
      bb.userData.spots.forEach((s, j) => {
        const lx = s.x + 0.2;
        const wx = b.x + Math.cos(b.rot) * lx;
        const wz = b.z - Math.sin(b.rot) * lx;
        const ax = b.x + Math.cos(b.rot) * lx + Math.sin(b.rot) * 0.95;
        const az = b.z - Math.sin(b.rot) * lx + Math.cos(b.rot) * 0.95;
        k.station({ id: `bunk-${i}-${j}`, label: "asleep in a bunk", activity: "sleep", bunk: true, pos: { x: wx, z: wz }, approach: { x: ax, z: az }, seat: s.y, face: b.rot + PI, tags: ["rest"] });
      });
    });
    k.footprints.push({ x: 0.7, z: -5.55, w: 0.7, d: 0.5 });
    k.place(new Group().add(mesh(rbox(2.2, 0.015, 1.4, 0.01), mat("#ddd0c2", { roughness: 1 }), { cast: false, pos: [0, 0.01, 0] })), { x: 3, z: -3 });
    k.station({ id: "bunk-chat", label: "chatting in the bunk room", activity: "sit", pos: { x: 3, z: -3 }, face: PI / 4, tags: ["social"] });
    return k;
  }
