      if (!t) return;
      const now = clock.now();
      this.source.stopWork(t);
      if (t.status === "wip" && t.workStart) t.progress = Math.min(0.95, Math.max(t.progress || 0, (now - t.workStart) / Math.max(1, t.workEnd - t.workStart)));
