      const x = m2.inbox.find((i) => i.id === mailId);
      if (!x) return;
      x.read = true;
      m2.inbox = m2.inbox.filter((i) => i.id !== mailId);
      m2.wall.push(x);
      if (m2.wall.length > 10) m2.wall.shift();
