      ok.addEventListener("click", done);
      input.addEventListener("keydown", (e) => e.key === "Enter" && done());
      row.appendChild(ok);
      node.appendChild(row);
      this.game.cards.show(node, { cls: "small" });
      setTimeout(() => input.focus(), 300);
